import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function GET(request: Request, context: { params: Promise<{ cityCode: string }> }) {
  try {
    const { cityCode } = await context.params;
    
    // 1. Đọc file JSON
    const filePath = path.join(process.cwd(), 'src', 'app', 'api', 'data', 'quan_huyen.json');
    const fileContents = fs.readFileSync(filePath, 'utf8');
    const rawData = JSON.parse(fileContents);
    
    // 2. Biến Object khổng lồ thành một Mảng (Array) chuẩn
    // Nếu rawData đã là mảng thì giữ nguyên, nếu là Object thì chuyển thành mảng
    const districtArray = Array.isArray(rawData) ? rawData : Object.values(rawData);
    
    // 3. Tiến hành lọc như bình thường
    const filteredDistricts = districtArray.filter(
      (district: any) => String(district.parent_code) === String(cityCode)
    );
    
    // 4. Trả mảng đã lọc về cho giao diện
    return NextResponse.json(filteredDistricts);
    
  } catch (error) {
    console.error("Lỗi đọc file quận huyện:", error);
    return NextResponse.json(
      { error: 'Không thể tải dữ liệu Quận/Huyện' }, 
      { status: 500 }
    );
  }
}